from datetime import datetime


def in_any_window(target_date: str, windows: list[tuple[str, str]]) -> bool:
    """Return whether target_date falls inside any date window.

    Validates all dates are in strict ISO calendar-date form (YYYY-MM-DD),
    checks that all windows have start <= end, and returns True if target_date
    falls within any window (inclusive boundaries).
