def _parse_date(date_str: str) -> datetime.date:
    """Parse and validate a date string in YYYY-MM-DD format.

    Raises ValueError if the date is malformed or represents an invalid calendar date.
    """
    try:
        # Strict validation: must be exactly YYYY-MM-DD format
        if len(date_str) != 10 or date_str[4] != '-' or date_str[7] != '-':
            raise ValueError(f"Malformed date: {date_str}")

        year = int(date_str[0:4])
