            pass  # OK, zero-padded
        elif date_str[8] != '0' and day < 10:
            raise ValueError(f"Malformed date: {date_str}")

        # datetime.date constructor validates the date
        return datetime.date(year, month, day)
    except (ValueError, IndexError) as e:
        raise ValueError(f"Malformed date: {date_str}") from e

